  4325		}
  4326		var header semanticHeader
  4327		if err := json.Unmarshal(scanner.Bytes(), &header); err != nil {
  4328			return semanticHeader{}, semanticCounts{}, fmt.Errorf("parse semantic snapshot header: %w", err)
