  4334			return semanticHeader{}, semanticCounts{}, fmt.Errorf("semantic snapshot repo_key %q does not match current repo %q", header.RepoKey, repoKey)
  4335		}
  4336		if err := validateSemanticSchema(header.SchemaVersion); err != nil {
  4337			return semanticHeader{}, semanticCounts{}, fmt.Errorf("semantic snapshot schema unsupported: %w", err)
  4338		}
