  2297		kindSet := lowerSet(spec.SymbolKinds)
  2298		var result semanticBoundaryResult
  2299		seenBoundaries := map[string]struct{}{}
  2300		seenHandlers := map[string]struct{}{}
  2301		for _, symbol := range sortedSemanticSymbols(symbolsByID) {
  2302			if !semanticKindInSet(symbol.Kind, kindSet) {
  2303				continue
  2304			}
