  2309			}
  2310		}
  2311		for _, relation := range relations {
  2312			if _, fromBoundary := seenBoundaries[relation.FromID]; !fromBoundary {
  2313				if _, toBoundary := seenBoundaries[relation.ToID]; !toBoundary {
  2314					continue
  2315				}
  2316			}
  2317			result.Relations = append(result.Relations, relation)
  2318			for _, id := range []string{relation.FromID, relation.ToID} {
  2319				symbol, ok := symbolsByID[id]
  2320				if !ok {
  2321					continue
  2322				}
  2323				if semanticKindInSet(symbol.Kind, kindSet) {
  2324					if _, seen := seenBoundaries[id]; !seen && len(result.Boundaries) < limit {
  2325						seenBoundaries[id] = struct{}{}
  2326						result.Boundaries = append(result.Boundaries, symbol)
  2327					}
  2328					continue
  2329				}
  2330				if _, seen := seenHandlers[id]; seen {
  2331					continue
  2332				}
  2333				seenHandlers[id] = struct{}{}
  2334				result.Handlers = append(result.Handlers, symbol)
  2335			}
  2336		}
  2337		return result, nil
  2338	}
