  2484	func findSemanticSymbolsInSQLite(storePath, query string, limit, offset int) ([]semanticRecord, error) {
  2485		db, err := sql.Open("sqlite", storePath)
  2486		if err != nil {
  2487			return nil, err
  2488		}
  2489		defer db.Close()
  2490		literal := strings.ToLower(strings.TrimSpace(query))
  2491		rows, err := db.Query(`SELECT s.id, s.kind, s.name, s.qualified_name, s.file_path, s.start_line, s.end_line, s.signature, s.language, s.stable_id_version
  2492	FROM symbols s
  2493	JOIN symbol_fts f ON f.id = s.id
  2494	WHERE instr(lower(f.text), ?) > 0
  2495	ORDER BY CASE WHEN lower(s.name) = lower(?) THEN 0 WHEN lower(s.qualified_name) = lower(?) THEN 1 ELSE 2 END, s.qualified_name
  2496	LIMIT ? OFFSET ?`, literal, query, query, limit, offset)
  2497		if err != nil {
  2498			return nil, err
  2499		}
  2500		defer rows.Close()
  2501		var results []semanticRecord
  2502		for rows.Next() {
  2503			var record semanticRecord
  2504			record.RecordType = "symbol"
  2505			if err := rows.Scan(&record.ID, &record.Kind, &record.Name, &record.QualifiedName, &record.FilePath, &record.StartLine, &record.EndLine, &record.Signature, &record.Language, &record.StableIDVersion); err != nil {
  2506				return nil, err
  2507			}
  2508			results = append(results, record)
  2509		}
  2510		return results, rows.Err()
  2511	}
