  2513	func findSemanticSymbols(snapshotPath, query string, limit, offset int) ([]semanticRecord, error) {
  2514		f, err := os.Open(snapshotPath)
  2515		if err != nil {
  2516			return nil, fmt.Errorf("open semantic snapshot: %w", err)
  2517		}
  2518		defer f.Close()
  2519		query = strings.ToLower(strings.TrimSpace(query))
  2520		scanner := newSemanticScanner(f)
  2521		first := true
  2522		var results []semanticRecord
  2523		seen := 0
  2524		for scanner.Scan() {
  2525			if first {
  2526				first = false
  2527				continue
  2528			}
  2529			text := bytes.TrimSpace(scanner.Bytes())
  2530			if len(text) == 0 {
  2531				continue
  2532			}
  2533			var record semanticRecord
  2534			if err := json.Unmarshal(text, &record); err != nil {
  2535				return nil, err
  2536			}
  2537			if record.RecordType != "symbol" {
  2538				continue
  2539			}
  2540			fields := []string{record.Name, record.QualifiedName, record.Signature, record.FilePath}
  2541			for _, field := range fields {
  2542				if strings.Contains(strings.ToLower(field), query) {
  2543					if seen < offset {
  2544						seen++
  2545						break
  2546					}
  2547					results = append(results, record)
  2548					seen++
  2549					break
  2550				}
  2551			}
  2552			if len(results) >= limit {
  2553				break
  2554			}
  2555		}
  2556		return results, scanner.Err()
  2557	}
