  2628	func traverseSemanticImpactSQLite(storePath string, roots []semanticRecord, depth, limit int) ([]semanticRecord, []semanticRecord, error) {
  2629		if len(roots) == 0 {
  2630			return nil, nil, nil
  2631		}
  2632		symbolsByID, err := loadSemanticSymbolsByIDSQLite(storePath)
  2633		if err != nil {
  2634			return nil, nil, err
  2635		}
  2636		frontier := map[string]struct{}{}
  2637		seen := map[string]struct{}{}
  2638		var symbols []semanticRecord
  2639		for _, root := range roots {
  2640			frontier[root.ID] = struct{}{}
  2641			if _, ok := seen[root.ID]; !ok {
  2642				seen[root.ID] = struct{}{}
  2643				symbols = append(symbols, root)
  2644			}
  2645		}
  2646		var relations []semanticRecord
  2647		for level := 0; level < depth && len(frontier) > 0; level++ {
  2648			current := make([]semanticRecord, 0, len(frontier))
  2649			for id := range frontier {
  2650				current = append(current, semanticRecord{ID: id})
  2651			}
  2652			edges, err := findSemanticRelationsForSymbolsInSQLite(storePath, current, limit*4)
  2653			if err != nil {
  2654				return nil, nil, err
  2655			}
  2656			next := map[string]struct{}{}
  2657			for _, edge := range edges {
  2658				relations = append(relations, edge)
  2659				for _, id := range []string{edge.FromID, edge.ToID} {
  2660					if _, ok := seen[id]; ok {
  2661						continue
  2662					}
  2663					if symbol, ok := symbolsByID[id]; ok && len(symbols) < limit {
  2664						seen[id] = struct{}{}
  2665						next[id] = struct{}{}
  2666						symbols = append(symbols, symbol)
  2667						if len(symbols) >= limit {
  2668							break
  2669						}
  2670					}
  2671				}
  2672			}
  2673			frontier = next
  2674		}
  2675		return symbols, relations, nil
  2676	}
