  3154	func readSemanticContextSnippet(path string, start, end int) (string, bool, error) {
  3155		if start <= 0 {
  3156			return "", false, errors.New("start line must be positive")
  3157		}
  3158		if end < start {
  3159			end = start
  3160		}
  3161		f, err := os.Open(path)
  3162		if err != nil {
  3163			return "", false, err
  3164		}
  3165		defer f.Close()
  3166		scanner := bufio.NewScanner(f)
  3167		scanner.Buffer(make([]byte, 0, 64*1024), 256*1024)
  3168		var lines []string
  3169		line := 0
  3170		bytesUsed := 0
  3171		truncated := false
  3172		for scanner.Scan() {
  3173			line++
  3174			if line < start {
  3175				continue
  3176			}
  3177			if line > end {
  3178				break
  3179			}
  3180			text := scanner.Text()
  3181			if len(lines) >= semanticContextMaxLines || bytesUsed+len(text) > semanticContextMaxBytes {
  3182				truncated = true
  3183				break
  3184			}
  3185			lines = append(lines, text)
  3186			bytesUsed += len(text)
  3187		}
  3188		if err := scanner.Err(); err != nil {
  3189			return "", false, err
  3190		}
  3191		if len(lines) == 0 {
  3192			return "", false, errors.New("line range outside file")
  3193		}
  3194		return strings.Join(lines, "\n"), truncated, nil
  3195	}
